nextflow_process {

    name "Test Process XENIUMRANGER_RENAME"
    script "../main.nf"
    process "XENIUMRANGER_RENAME"

    tag "modules"
    tag "modules_nfcore"
    tag "xeniumranger"
    tag "xeniumranger/rename"

    test("xeniumranger rename") {
        def bundle
        setup {
            bundle = extract('https://raw.githubusercontent.com/nf-core/test-datasets/spatialxe/Xenium_V1_Protein_Human_Kidney_tiny_outs.zip')
        }

        when {
            process {
                """
                input[0] = [
                    [id: "test_xeniumranger_rename"],
                    file('${bundle}'),
                    "test_region",
                    "test_cassette"
                ]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert process.out.outs != null },
                { assert file(process.out.outs.get(0).get(1)).isDirectory() },
                { assert file(process.out.outs.get(0).get(1) + "/analysis_summary.html").exists() },
                { assert file(process.out.outs.get(0).get(1) + "/cells.csv.gz").exists() },
                { assert file(process.out.outs.get(0).get(1) + "/cells.parquet").exists() },
                { assert file(process.out.outs.get(0).get(1) + "/cells.zarr.zip").exists() },
                { assert file(process.out.outs.get(0).get(1) + "/transcripts.parquet").exists() },
                { assert file(process.out.outs.get(0).get(1) + "/transcripts.zarr.zip").exists() },
                { assert file(process.out.outs.get(0).get(1) + "/analysis.zarr.zip").exists() },
                { assert file(process.out.outs.get(0).get(1) + "/cell_feature_matrix.zarr.zip").exists() },
                { assert snapshot(process.out.versions_xeniumranger).match()},
            )
        }
    }

    test("xeniumranger rename stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [id: "test_xeniumranger_rename"],
                    [],
                    "test_region",
                    "test_cassette"
                ]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}
